import RemoveRedEyeIcon from "@mui/icons-material/RemoveRedEye";
import { LazyLoadImage } from "react-lazy-load-image-component";
import CommonUtil from "../../utils/Function";

interface DirtListProps {
  list: any[];
}

const DirtList = ({ list }: DirtListProps) => {
  if (!list?.length) return null;

  return (
    <div className="grid grid-cols-2 gap-2 p-2 pb-40">
      {list.map((post) => {
        const views = post.view_total ?? post.total_views ?? post.views ?? post.view_count ?? post.watch_count;

        return (
          <a
            key={post.id}
            href={post.external_url}
            target="_blank"
            rel="noreferrer"
            className="block bg-white dark:bg-nbk rounded overflow-hidden shadow"
          >
            <div className="relative aspect-[2/3] w-full overflow-hidden">
              <LazyLoadImage
                className="absolute inset-0 w-full h-full object-cover bg-gy"
                placeholderSrc="/images/cover_default.jpg"
                src={post.images?.[0] || "/images/cover_default.jpg"}
                alt={post.title || ""}
              />
              {post.image_total > 1 && (
                <span className="absolute top-1 right-1 min-w-10 h-10 px-1 rounded-full bg-black/60 text-white text-base font-medium inline-flex items-center justify-center">
                  +{post.image_total - 1}
                </span>
              )}
            </div>
            <div className="p-2">
              <p className="line-clamp-2 text-base font-medium dark:text-white leading-6">{post.title}</p>
              {post.description && (
                <p className="text-base dark:text-white leading-6 mt-1 line-clamp-2">{post.description}</p>
              )}
              {(views != null || post.updated_at) && (
                <div className="mt-3 flex items-center justify-between text-t08 text-gy dark:text-tgy">
                  <span className="flex items-center">
                    {views != null && (
                      <>
                        <RemoveRedEyeIcon className="text-sm mr-1" />
                        {CommonUtil.fomatFloat(views, 1)}
                      </>
                    )}
                  </span>
                  {post.updated_at && <span>{post.updated_at}</span>}
                </div>
              )}
            </div>
          </a>
        );
      })}
    </div>
  );
};

export default DirtList;
